content.text:
The evidence points to one root cause: ts-train-food-service lost a pod, and its failure reached users through ts-food-service's 500s on the ts-ui-dashboard food endpoint. The preserve→user latency I checked was noise.

```json
{
  "root_causes": [
    {
      "service": "ts-train-food-service",
      "fault_kind": "pod_failure",
      "evidence": [
        {
          "kind": "metric",
          "sql": "SELECT attr_k8s_pod_name, min(time) AS first_seen, max(time) AS last_seen, count(*) AS n FROM abnormal_metrics WHERE attr_k8s_pod_name LIKE 'ts-train-food%' GROUP BY attr_k8s_pod_name ORDER BY 1",
          "claim": "In the incident window, pod zb6b2 emits only 2 points at 05:58:09 and stops, while new pod 64vkq appears at 05:58:13 and runs on."
        },
        {
          "kind": "log",
          "sql": "SELECT time, service_name, level, message FROM abnormal_logs WHERE service_name='ts-food-service' AND message LIKE '%ts-train-food-service%Connection refused%' ORDER BY time LIMIT 5",
          "claim": "ts-food-service logs connection-refused I/O errors calling ts-train-food-service during the pod gap, starting 05:58:12."
        },
        {
          "kind": "trace",
          "sql": "SELECT min(time) AS first_err, max(time) AS last_err, count(*) AS n FROM abnormal_traces WHERE service_name='ts-food-service' AND span_name='GET' AND attr_status_code='Error'",
          "claim": "108 failed outgoing GET calls from ts-food-service, between 05:58:12 and 05:59:19, with no child spans."
        }
      ]
    },
    {
      "service": "ts-food-service",
      "fault_kind": "application_exception",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_status_code, attr_http_response_status_code, count(*) n FROM abnormal_traces WHERE service_name IN ('ts-food-service','ts-ui-dashboard') AND span_name LIKE 'GET /api/v1/foodservice/foods%' GROUP BY ALL ORDER BY 1,2,3",
          "claim": "Food endpoint returns HTTP 500 in 108 of about 408 requests at ts-food-service and at ts-ui-dashboard."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-train-food-service",
      "to": "ts-food-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT c.service_name, c.span_name, count(*) n, avg(CASE WHEN c.attr_status_code='Error' THEN 1 ELSE 0 END) err FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-food-service' AND c.service_name LIKE 'ts-train%' GROUP BY ALL",
          "claim": "ts-food-service's calls to ts-train-food-service complete with no error in spans, while other failing calls from it have no child span."
        }
      ]
    },
    {
      "from": "ts-food-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, attr_status_code, attr_http_response_status_code, count(*) n FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND span_name LIKE 'GET /api/v1/foodservice/foods%' GROUP BY ALL",
          "claim": "ts-ui-dashboard's food endpoint returns 500 on 108 requests, matching the failing ts-food-service calls."
        }
      ]
    }
  ]
}
```

